'use strict';
/* ICT12 v3 – Teacher portal (teacher + admin), student self-report. Layered on app.js/ui.js globals ($, esc, api, toast, app, user, tab). */
const PT={view:'overview',data:null,student:null,cls:'',exam:'',cart:[],live:null,liveTimer:null,teacher:null,bank:{type:'mcq',lesson:'',level:'',q:''}};
const fmt=n=>n==null||!Number.isFinite(+n)?'—':(Math.round(n*100)/100).toLocaleString('vi-VN');
const fmtD=v=>v?new Date(v).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour12:false,day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const RATE_CLS={'Giỏi':'r-good','Khá':'r-fair','Đạt':'r-pass','Chưa đạt':'r-fail'};
const rateTag=r=>r?`<span class="rate ${RATE_CLS[r]}">${esc(r)}</span>`:'<span class="rate r-none">Chưa xếp</span>';
const ST={on_time:['Đúng hạn','ok'],late:['Làm bù sau hạn','warn'],missing:['Thiếu','bad'],open:['Đang mở','info'],in_progress:['Đang làm','info'],upcoming:['Sắp mở','muted']};
const stTag=s=>`<span class="st st-${(ST[s]||['',''])[1]}">${(ST[s]||[s])[0]}</span>`;
const VK={tab:'Chuyển tab',blur:'Rời cửa sổ',fullscreen:'Thoát toàn màn hình',reload:'Tải lại trang',shortcut:'Phím tắt bị chặn'};
function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function downloadB64(name,b64){download(name,new Blob([Uint8Array.from(atob(b64),c=>c.charCodeAt(0))],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}))}
function downloadCSV(name,rows){const csv='\uFEFF'+rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return/[",\n;]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}).join(',')).join('\r\n');download(name,new Blob([csv],{type:'text/csv;charset=utf-8'}))}
async function run(btn,fn){if(btn)btn.disabled=true;try{return await fn()}catch(e){toast(e.message,true)}finally{if(btn)btn.disabled=false}}
const isAdminP=()=>user&&user.role==='admin';
/* ---------- charts (inline SVG, theme-aware via currentColor/CSS vars) ---------- */
function lineChart(points,{h=180,max=10,label=p=>p.title}={}){if(!points.length)return'<p class="small muted">Chưa có dữ liệu điểm.</p>';const w=640,pad=30,n=points.length,x=i=>pad+(n===1?(w-2*pad)/2:i*(w-2*pad)/(n-1)),y=v=>h-pad-(v/max)*(h-2*pad);
 const grid=[0,2.5,5,7.5,10].map(v=>`<line x1="${pad}" x2="${w-pad/2}" y1="${y(v)}" y2="${y(v)}" class="grid"/><text x="4" y="${y(v)+4}" class="ax">${v}</text>`).join('');const path=points.map((p,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(p.score).toFixed(1)).join(' ');
 return`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Biểu đồ điểm theo thời gian">${grid}<line x1="${pad}" x2="${w-pad/2}" y1="${y(5)}" y2="${y(5)}" class="pass"/><path d="${path}" class="line"/>${points.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.score)}" r="4" class="${p.practice?'dot practice':'dot'}"><title>${esc(label(p))}: ${fmt(p.score)} · ${fmtD(p.at)}</title></circle>`).join('')}</svg>`}
function barChart(rows,{h=170,valueKey='count',labelKey='label',color=i=>''}={}){const w=640,pad=26,max=Math.max(1,...rows.map(r=>r[valueKey])),bw=(w-2*pad)/rows.length;return`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Biểu đồ cột">${rows.map((r,i)=>{const bh=(r[valueKey]/max)*(h-2*pad);return`<rect x="${pad+i*bw+3}" y="${h-pad-bh}" width="${bw-6}" height="${bh}" rx="4" class="cbar ${color(i)}"><title>${esc(r[labelKey])}: ${r[valueKey]}</title></rect><text x="${pad+i*bw+bw/2}" y="${h-8}" class="ax" text-anchor="middle">${esc(r[labelKey])}</text>${r[valueKey]?`<text x="${pad+i*bw+bw/2}" y="${h-pad-bh-4}" class="ax v" text-anchor="middle">${r[valueKey]}</text>`:''}`}).join('')}</svg>`}
const heatColor=l=>!l.total?'h-none':l.total<5?'h-few':l.accuracy>=85?'h-4':l.accuracy>=65?'h-3':l.accuracy>=50?'h-2':'h-1';
function heatmap(ls){return`<div class="heat" role="list">${ls.map(l=>`<div class="hcell ${heatColor(l)}" role="listitem" title="Bài ${l.id} – ${esc(l.title)}: ${l.total?l.accuracy+'% đúng / '+l.total+' lượt':'chưa có dữ liệu'}"><b>${l.id}</b><span>${l.total?l.accuracy+'%':'–'}</span></div>`).join('')}</div><div class="heat-legend"><span class="hcell h-1"></span>&lt;50% <span class="hcell h-2"></span>50–64 <span class="hcell h-3"></span>65–84 <span class="hcell h-4"></span>≥85 <span class="hcell h-few"></span>ít dữ liệu <span class="hcell h-none"></span>chưa làm</div>`}
const hbars=rows=>rows.length?`<div class="hbars">${rows.map(r=>`<div class="hbar"><span class="hb-label">${esc(r.label)}</span><span class="hb-track"><i style="width:${Math.max(2,r.value)}%" class="${r.value<50?'bad':r.value<65?'warn':'ok'}"></i></span><b>${r.value}%</b></div>`).join('')}</div>`:'<p class="small muted">Chưa có dữ liệu.</p>';
/* ---------- shell ---------- */
function menu(){const T=[['overview','◎','Tổng quan'],['classes','▦','Lớp học'],['students','☺','Học sinh'],['analytics','▤','Phân tích lớp'],['assign','✎','Giao bài'],['builder','✚','Tạo đề'],['bank','❏','Ngân hàng câu hỏi'],['announce','✉','Thông báo'],['learn','✦','Tự học & tài liệu'],['live','●','Trực tuyến'],['password','⚿','Mật khẩu']];
 if(isAdminP())T.splice(1,0,['teachers','♜','Giáo viên']);return T}
async function renderPortal(view){if(view)PT.view=view;clearInterval(PT.liveTimer);
 app.innerHTML=`<section class="portal"><aside class="p-side" aria-label="Điều hướng cổng giáo viên"><div class="p-who"><span class="p-avatar">${esc((user.name||'?').trim().split(' ').at(-1)[0]||'G')}</span><div><b>${esc(user.name)}</b><small>${isAdminP()?'Quản trị viên · toàn trường':'Giáo viên'}</small></div></div><nav>${menu().map(([id,ic,name])=>`<button data-pv="${id}" class="${PT.view===id||(PT.view==='report'&&id==='students')||(PT.view==='teacher'&&id==='teachers')?'on':''}"><i aria-hidden="true">${ic}</i><span>${name}</span></button>`).join('')}${isAdminP()?'<button data-pv="legacy" class="legacy"><i>↩</i><span>Quản trị cũ</span></button>':''}</nav></aside><div class="p-main" id="p-main"><p class="loading">Đang tải…</p></div></section>`;
 document.querySelectorAll('[data-pv]').forEach(b=>b.onclick=()=>{if(b.dataset.pv==='legacy'){tab='students';return renderAdmin()}PT.student=null;renderPortal(b.dataset.pv)});
 const m=$('#p-main');try{if(!PT.data||['overview','classes','students','assign','announce','builder','teachers'].includes(PT.view))PT.data=await api('portalData');const V={overview,classes:classesView,students:studentsView,report:reportView,analytics:analyticsView,assign:assignView,builder:builderView,bank:bankView,announce:announceView,live:liveView,learn:el=>learnPortalView(el),teachers:teachersView,teacher:teacherView,password:el=>passwordHTML(el)}[PT.view]||overview;await V(m)}catch(e){m.innerHTML=`<div class="empty"><h2>Chưa tải được dữ liệu</h2><p>${esc(e.message)}</p><button class="primary" id="p-retry">Thử lại</button></div>`;$('#p-retry').onclick=()=>renderPortal()}}
const head=(t,s,actions='')=>`<div class="p-head"><div><p class="eyebrow">${isAdminP()?'QUẢN TRỊ · CỔNG GIÁO VIÊN':'CỔNG GIÁO VIÊN'}</p><h1>${t}</h1>${s?`<p class="muted">${s}</p>`:''}</div><div class="p-actions">${actions}</div></div>`;
const metric=(v,l,cls='')=>`<div class="metric ${cls}"><strong>${v}</strong><span>${l}</span></div>`;
const classOpts=(sel,all=false)=>(all?'<option value="">Tất cả lớp của tôi</option>':'')+PT.data.classes.filter(c=>!c.disabled).map(c=>`<option value="${esc(c.id)}" ${sel===c.id?'selected':''}>${esc(c.name)} (${c.students} HS)</option>`).join('');
/* ---------- overview ---------- */
async function overview(m){const d=PT.data,now=Date.now(),act=d.assignments.filter(a=>!a.disabled&&a.closesAt>now);
 m.innerHTML=head('Chào '+esc(user.name.split(' ').at(-1))+', hôm nay lớp học thế nào?','Theo dõi tiến độ, phát hiện học sinh cần hỗ trợ và giao bài đúng trọng tâm.',`<button class="primary" data-go="assign">✎ Giao bài</button><button class="ghost" data-go="analytics">▤ Phân tích lớp</button>`)+
 `<div class="metric-grid p-metrics">${metric(d.classes.filter(c=>!c.disabled).length,'Lớp đang dạy')}${metric(d.students.length,'Học sinh')}${metric(act.length,'Bài giao đang mở')}${metric('<span id="ov-online">…</span>','Đang trực tuyến')}${metric('<span id="ov-risk">…</span>','HS cần quan tâm','warn')}</div>
 <div class="p-grid2"><div class="card"><h2>Bài giao sắp đến hạn</h2>${act.length?`<ul class="plain">${act.sort((a,b)=>a.closesAt-b.closesAt).slice(0,6).map(a=>`<li><b>${esc(a.title)}</b> · ${esc(a.className)}<br><small class="muted">Hạn ${fmtD(a.closesAt)} · ${a.attemptLimit||1} lượt</small></li>`).join('')}</ul>`:'<p class="muted small">Chưa có bài giao đang mở.</p>'}</div>
 <div class="card"><h2>Học sinh cần quan tâm</h2><div id="ov-risklist"><p class="loading">Đang phân tích…</p></div></div></div>
 ${d.classes.length?'':`<div class="notice">Bắt đầu: vào <b>Lớp học</b> để tạo lớp, sau đó nhập danh sách học sinh từ Excel/CSV — hệ thống tự tạo tài khoản và mật khẩu để bạn tải về.</div>`}`;
 m.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>renderPortal(b.dataset.go));
 try{const [live,st]=await Promise.all([api('liveStatus'),d.students.length?api('classStats',{}):null]);$('#ov-online')&&($('#ov-online').textContent=live.rows.filter(r=>r.online||r.inExam).length);if(st){$('#ov-risk').textContent=st.analytics.summary.atRisk;$('#ov-risklist').innerHTML=riskList(st.analytics.atRisk.slice(0,8));bindStudentLinks(m)}else{$('#ov-risk').textContent='0';$('#ov-risklist').innerHTML='<p class="muted small">Chưa có học sinh.</p>'}}catch(e){toast(e.message,true)}}
const riskList=rows=>rows.length?`<ul class="plain risk">${rows.map(r=>`<li><button class="link" data-student="${esc(r.id)}">${esc(r.name)}</button> <small class="muted">${esc(r.className)}</small><br>${r.risks.map(x=>`<span class="chip warn">${esc(x)}</span>`).join(' ')}</li>`).join('')}</ul>`:'<p class="muted small">Không có học sinh nào cần cảnh báo. 👍</p>';
function bindStudentLinks(root){root.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>{PT.student=b.dataset.student;renderPortal('report')})}
/* ---------- classes ---------- */
async function classesView(m){const d=PT.data;
 m.innerHTML=head('Lớp học','Mỗi lớp thuộc về một giáo viên. Tên lớp là duy nhất trong toàn trường (ví dụ 12A1-2026).')+
 `<div class="p-grid2"><form class="card" id="cls-form"><h2>Tạo lớp mới</h2><label for="cls-name">Tên lớp</label><input id="cls-name" maxlength="50" required placeholder="12A1-2026"><label for="cls-year">Năm học</label><input id="cls-year" maxlength="20" placeholder="2026–2027">${isAdminP()?`<label for="cls-owner">Giáo viên phụ trách</label><select id="cls-owner"><option value="">(Quản trị viên)</option>${(d.teachers||[]).map(t=>`<option value="${esc(t.id)}">${esc(t.name)} · ${esc(t.username)}</option>`).join('')}</select>`:''}<div class="form-row"><button class="primary">Tạo lớp</button></div></form>
 <form class="card" id="imp-form"><h2>Nhập học sinh vào lớp</h2><p class="small muted">Tải lên tệp <b>Excel (.xlsx)</b> hoặc <b>CSV</b> có cột “Họ tên” (tuỳ chọn cột “Tài khoản”), hoặc dán mỗi dòng một họ tên. Hệ thống tự tạo tên đăng nhập và mật khẩu.</p><label for="imp-class">Lớp</label><select id="imp-class" required>${classOpts(PT.cls)}</select><label for="imp-file">Tệp danh sách</label><input type="file" id="imp-file" accept=".xlsx,.csv,.txt"><label for="imp-text">hoặc dán danh sách</label><textarea id="imp-text" rows="4" placeholder="Nguyễn Minh An&#10;Trần Thị Bình"></textarea><div class="form-row"><button class="ghost" type="button" id="imp-preview">Xem trước</button><button class="primary">Tạo tài khoản</button></div><div id="imp-out"></div></form></div>
 <div class="section-head"><h2>Danh sách lớp</h2></div><div class="class-cards">${d.classes.map(c=>`<article class="card class-card ${c.disabled?'archived':''}"><div><h3>${esc(c.name)}</h3><p class="small muted">${c.students} học sinh${c.schoolYear?' · '+esc(c.schoolYear):''}${c.disabled?' · đã lưu trữ':''}${isAdminP()?' · GV: '+esc((d.teachers||[]).find(t=>t.id===c.ownerId)?.name||'Quản trị viên'):''}</p></div><div class="row-actions"><button class="ghost sm" data-cstats="${esc(c.id)}">Phân tích</button><button class="ghost sm" data-cstudents="${esc(c.name)}">Học sinh</button><button class="ghost sm" data-carch="${esc(c.id)}" data-v="${c.disabled?0:1}">${c.disabled?'Mở lại':'Lưu trữ'}</button>${isAdminP()?`<select class="sm" data-cowner="${esc(c.id)}" aria-label="Giáo viên phụ trách ${esc(c.name)}"><option value="">(Quản trị viên)</option>${(d.teachers||[]).map(t=>`<option value="${esc(t.id)}" ${t.id===c.ownerId?'selected':''}>${esc(t.name)}</option>`).join('')}</select>`:''}</div></article>`).join('')||'<p class="muted">Chưa có lớp nào.</p>'}</div>`;
 $('#cls-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{const x=await api('classSave',{name:$('#cls-name').value,schoolYear:$('#cls-year').value,ownerId:$('#cls-owner')?.value||undefined});PT.cls=x.id;toast('Đã tạo lớp.');renderPortal('classes')})};
 const payload=async()=>{const f=$('#imp-file').files[0];if(f){if(f.size>140000)throw Error('Tệp quá lớn (tối đa 140 KB).');const buf=new Uint8Array(await f.arrayBuffer());let bin='';for(let i=0;i<buf.length;i+=8192)bin+=String.fromCharCode(...buf.subarray(i,i+8192));return{base64:btoa(bin),filename:f.name}}const t=$('#imp-text').value.trim();if(!t)throw Error('Chọn tệp hoặc dán danh sách.');return{text:/[,;\t]/.test(t.split('\n')[0])?t:'Họ tên\n'+t}};
 $('#imp-preview').onclick=e=>run(e.target,async()=>{const x=await api('studentsPreview',await payload());$('#imp-out').innerHTML=`<p class="small">Đọc được <b>${x.rows.length}</b> học sinh:</p><ol class="small preview">${x.rows.slice(0,50).map(r=>`<li>${esc(r.name)}${r.username?' · '+esc(r.username):''}</li>`).join('')}</ol>`});
 $('#imp-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{const classId=$('#imp-class').value;if(!classId)throw Error('Hãy tạo lớp trước.');const x=await api('studentsImport',{classId,...await payload()});credentialsOut($('#imp-out'),x.results,'tai-khoan-hoc-sinh');PT.data=await api('portalData')})};
 m.querySelectorAll('[data-carch]').forEach(b=>b.onclick=()=>run(b,async()=>{await api('classArchive',{id:b.dataset.carch,archived:b.dataset.v==='1'});renderPortal('classes')}));
 m.querySelectorAll('[data-cstats]').forEach(b=>b.onclick=()=>{PT.cls=b.dataset.cstats;renderPortal('analytics')});
 m.querySelectorAll('[data-cstudents]').forEach(b=>b.onclick=()=>{PT.studentFilter=b.dataset.cstudents;renderPortal('students')});
 m.querySelectorAll('[data-cowner]').forEach(s=>s.onchange=()=>run(s,async()=>{await api('classOwner',{classId:s.dataset.cowner,teacherId:s.value});toast('Đã cập nhật giáo viên phụ trách.')}))}
function credentialsOut(el,results,file){const ok=results.filter(r=>!r.error),bad=results.filter(r=>r.error);el.innerHTML=`<div class="notice"><b>Đã tạo ${ok.length} tài khoản.</b> Mật khẩu chỉ hiển thị <b>một lần</b> — hãy tải về ngay.${bad.length?`<br>${bad.length} dòng lỗi: ${bad.map(b=>esc(b.name+' ('+b.error+')')).join(', ')}`:''}</div>${ok.length?`<div class="form-row"><button class="primary" type="button" id="cred-csv">⬇ Tải CSV (Excel)</button><button class="ghost" type="button" id="cred-print">🖨 In phiếu tài khoản</button></div><div class="table-wrap"><table class="cred"><thead><tr><th>Họ tên</th><th>Tài khoản</th><th>Mật khẩu</th><th>Lớp</th></tr></thead><tbody>${ok.map(r=>`<tr><td>${esc(r.name)}</td><td><code>${esc(r.username)}</code></td><td><code>${esc(r.password)}</code></td><td>${esc(r.className||'')}</td></tr>`).join('')}</tbody></table></div>`:''}`;
 if(ok.length){$('#cred-csv').onclick=()=>downloadCSV(file+'.csv',[['Họ tên','Tài khoản','Mật khẩu','Lớp','Địa chỉ'],...ok.map(r=>[r.name,r.username,r.password,r.className||'',location.origin])]);$('#cred-print').onclick=()=>{const w=document.createElement('div');w.className='print-slips';w.innerHTML=ok.map(r=>`<div class="slip"><b>${esc(r.name)}</b><span>${esc(r.className||'')}</span><span>Địa chỉ: ${esc(location.origin)}</span><span>Tài khoản: <code>${esc(r.username)}</code></span><span>Mật khẩu: <code>${esc(r.password)}</code></span></div>`).join('');document.body.appendChild(w);document.body.classList.add('printing-slips');print();setTimeout(()=>{w.remove();document.body.classList.remove('printing-slips')},500)}}}
/* ---------- students ---------- */
async function studentsView(m){const d=PT.data;const live=await api('liveStatus').catch(()=>({rows:[]}));const L=new Map(live.rows.map(r=>[r.id,r]));const filt=PT.studentFilter||'';
 m.innerHTML=head('Học sinh',`${d.students.length} học sinh trong các lớp ${isAdminP()?'toàn trường':'của bạn'}.`,`<button class="ghost" data-go="classes">＋ Nhập học sinh</button>`)+
 `<div class="toolbar p-toolbar"><input id="st-q" placeholder="Tìm tên, tài khoản" aria-label="Tìm học sinh"><select id="st-class" aria-label="Lọc lớp"><option value="">Tất cả lớp</option>${d.classes.map(c=>`<option ${filt===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select><span class="spacer"></span><select id="mv-class" aria-label="Chuyển tới lớp">${classOpts('')}</select><button class="ghost" id="mv-btn">Chuyển lớp các HS đã chọn</button></div>
 <div class="table-wrap"><table class="p-table"><thead><tr><th><input type="checkbox" id="st-all" aria-label="Chọn tất cả"></th><th>Học sinh</th><th>Lớp</th><th>Trạng thái</th><th>Hoạt động</th><th></th></tr></thead><tbody id="st-body"></tbody></table></div><div id="st-out"></div>`;
 m.querySelector('[data-go]').onclick=()=>renderPortal('classes');
 const draw=()=>{const q=$('#st-q').value.toLowerCase(),c=$('#st-class').value;PT.studentFilter=c;const rows=d.students.filter(s=>(!c||s.className===c)&&(!q||(s.name+' '+s.username).toLowerCase().includes(q))).sort((a,b)=>a.className.localeCompare(b.className)||a.name.split(' ').at(-1).localeCompare(b.name.split(' ').at(-1),'vi'));
  $('#st-body').innerHTML=rows.map(s=>{const l=L.get(s.id)||{};return`<tr><td><input type="checkbox" class="st-pick" value="${esc(s.id)}" aria-label="Chọn ${esc(s.name)}"></td><td><button class="link" data-student="${esc(s.id)}">${esc(s.name)}</button><br><small class="muted"><code>${esc(s.username)}</code></small></td><td>${esc(s.className)}</td><td>${s.locked?'<span class="st st-bad">Đã khóa</span>':l.inExam?`<span class="st st-info">● Đang làm bài ${esc(l.progress||'')}</span>`:l.online?'<span class="st st-ok">● Trực tuyến</span>':'<span class="st st-muted">Ngoại tuyến</span>'}</td><td><small>${l.lastSeen?fmtD(l.lastSeen):'—'}</small></td><td class="row-actions"><button class="ghost sm" data-student="${esc(s.id)}">Đánh giá</button><button class="ghost sm" data-reset="${esc(s.id)}">Đặt lại MK</button><button class="ghost sm" data-lock="${esc(s.id)}" data-v="${s.locked?0:1}">${s.locked?'Mở khóa':'Khóa'}</button></td></tr>`}).join('')||'<tr><td colspan="6" class="muted">Không có học sinh.</td></tr>';
  bindStudentLinks(m);m.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>run(b,async()=>{if(!confirm('Đặt lại mật khẩu cho học sinh này? Phiên đăng nhập cũ sẽ bị đăng xuất.'))return;const x=await api('studentReset',{id:b.dataset.reset});credentialsOut($('#st-out'),[{...x,className:d.students.find(s=>s.id===b.dataset.reset)?.className}],'mat-khau-moi');$('#st-out').scrollIntoView({behavior:'smooth'})}));
  m.querySelectorAll('[data-lock]').forEach(b=>b.onclick=()=>run(b,async()=>{await api('studentLock',{id:b.dataset.lock,locked:b.dataset.v==='1'});PT.data=await api('portalData');renderPortal('students')}))};
 draw();$('#st-q').oninput=draw;$('#st-class').onchange=draw;$('#st-all').onchange=e=>m.querySelectorAll('.st-pick').forEach(x=>x.checked=e.target.checked);
 $('#mv-btn').onclick=e=>run(e.target,async()=>{const ids=[...m.querySelectorAll('.st-pick:checked')].map(x=>x.value);if(!ids.length)throw Error('Chọn ít nhất 1 học sinh.');const x=await api('studentMove',{ids,classId:$('#mv-class').value});toast('Đã chuyển '+x.moved+' học sinh.');PT.data=await api('portalData');renderPortal('students')})}
/* ---------- per-student evaluation ---------- */
async function reportView(m){const x=await api('studentReport',{id:PT.student});const r=x.report;PT.report=r;m.innerHTML=reportHTML(r,false);bindReport(m,r);if(typeof learnReportSection==='function')learnReportSection(m,PT.student)}
function reportHTML(r,self){const s=r.summary;return`<article class="report" id="report">${self?'':`<div class="p-head no-print"><div><p class="eyebrow">ĐÁNH GIÁ CHI TIẾT HỌC SINH</p></div><div class="p-actions"><button class="ghost" id="rp-back">← Danh sách</button><button class="primary" id="rp-print">🖨 In / Lưu PDF</button></div></div>`}
 <header class="rp-top"><div><h1>${esc(r.student.name)}</h1><p class="muted">${self?'Báo cáo học tập của tôi':'Tài khoản <code>'+esc(r.student.id)+'</code>'} · Lớp ${esc(r.student.className||'—')} · Lập lúc ${fmtD(r.generatedAt)} (UTC+7)</p></div><div class="rp-rating">${rateTag(s.rating)}<small>Mức đánh giá (TB ${s.recentAverage!=null?'10 bài gần nhất':'—'})</small></div></header>
 <div class="metric-grid rp-metrics">${metric(fmt(s.recentAverage??s.average),'Điểm TB gần đây /10')}${metric(fmt(s.best),'Điểm cao nhất')}${metric(s.gradedCount,'Bài kiểm tra')}${metric(s.practiceCount,'Lượt luyện tập')}${metric(esc(s.trend),'Xu hướng',s.trend==='Giảm sút'?'warn':'')}${metric(r.completion.rate==null?'—':r.completion.rate+'%','Hoàn thành bài giao đúng hạn')}</div>
 <section class="card rp-remarks"><h2>Nhận xét</h2><ul>${r.remarks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Gợi ý ôn tập</h3><ol>${r.suggestions.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>
 <div class="p-grid2"><section class="card"><h2>Diễn biến điểm</h2>${lineChart(r.timeline)}<p class="small muted">Chấm tròn rỗng = luyện tập; đường nét đứt = mốc 5 điểm.</p></section>
 <section class="card"><h2>Theo chủ đề</h2>${hbars(r.topics.filter(t=>t.total).map(t=>({label:'Chủ đề '+t.id+' · '+t.name,value:t.accuracy})))}<p class="small"><b>Mạnh:</b> ${r.strongest.map(x=>esc(x.label+' ('+x.accuracy+'%)')).join(', ')||'—'}<br><b>Cần củng cố:</b> ${r.weakest.map(x=>esc(x.label+' ('+x.accuracy+'%)')).join(', ')||'—'}</p></section></div>
 <section class="card"><h2>Mức độ thành thạo theo bài (1–28)</h2>${heatmap(r.lessons)}</section>
 <div class="p-grid2"><section class="card"><h2>Thời gian làm bài</h2>${r.time.sampled?`<div class="metric-grid mini">${metric(fmt(r.time.average)+'s','TB mỗi câu')}${metric(fmt(r.time.median)+'s','Trung vị')}${metric(r.time.fastWrong,'Sai trong &lt;3s','warn')}${metric(r.time.timeouts,'Hết giờ')}</div>${barChart(r.time.buckets,{h:140})}`:'<p class="small muted">Chưa có dữ liệu thời gian (được ghi nhận từ phiên bản v3).</p>'}</section>
 <section class="card"><h2>Bài được giao</h2>${r.assignments.length?`<div class="table-wrap"><table><thead><tr><th>Bài</th><th>Hạn</th><th>Trạng thái</th><th>Điểm</th></tr></thead><tbody>${r.assignments.map(a=>`<tr><td>${esc(a.title)}</td><td><small>${fmtD(a.closesAt)}</small></td><td>${stTag(a.status)}</td><td>${fmt(a.score)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="small muted">Chưa có bài giao cho lớp.</p>'}</section></div>
 ${self?'':`<section class="card"><h2>Câu hay sai & nhầm lẫn thường gặp</h2>${r.misconceptions.length?`<div class="notice small">${r.misconceptions.map(x=>`Bài ${x.lesson}: hay chọn “${esc(x.chosen)}” thay vì “${esc(x.correct)}” (${x.count} lần)`).join('<br>')}</div>`:''}${r.missed.length?`<div class="table-wrap"><table><thead><tr><th>Bài</th><th>Câu hỏi</th><th>Sai/Lượt</th><th>Hay chọn</th><th>Đáp án</th></tr></thead><tbody>${r.missed.map(q=>`<tr><td>${q.lesson}</td><td class="qtext">${esc(q.question)}</td><td>${q.wrong}/${q.seen}${q.repeated?' <span class="chip warn">lặp lại</span>':''}</td><td>${esc(q.commonWrong?.text||'')}</td><td>${esc(q.answerText)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="small muted">Chưa có câu sai.</p>'}</section>
 <section class="card"><h2>Nhật ký chống gian lận</h2><p class="small">Tổng ${r.violations.total} sự kiện${Object.keys(r.violations.byKind).length?': '+Object.entries(r.violations.byKind).map(([k,v])=>esc((VK[k]||k)+' ×'+v)).join(', '):''}.</p>${r.violations.log.length?`<div class="table-wrap scroll-y"><table><thead><tr><th>Thời điểm (UTC+7)</th><th>Loại</th><th>Câu</th><th>Bài làm</th></tr></thead><tbody>${r.violations.log.map(v=>`<tr><td>${fmtD(v.at)}</td><td>${esc(VK[v.kind]||v.kind)}</td><td>${v.questionIndex!=null?v.questionIndex+1:'—'}</td><td><button class="link" data-attempt="${esc(v.attemptId)}">Xem</button></td></tr>`).join('')}</tbody></table></div>`:''}</section>`}
 <section class="card"><h2>Lịch sử làm bài</h2><div class="table-wrap"><table><thead><tr><th>Bắt đầu</th><th>Đề</th><th>Loại</th><th>Điểm</th><th>Thời lượng</th><th>Vi phạm</th>${self?'':'<th></th>'}</tr></thead><tbody>${r.attempts.map(a=>`<tr><td><small>${fmtD(a.startedAt)}</small></td><td>${esc(a.title)}</td><td>${a.practice?'Luyện tập':a.assignmentId?'Bài giao':'Kiểm tra'}</td><td>${a.status==='submitted'?'<b>'+fmt(a.score)+'</b>':a.status==='active'?'<span class="st st-info">Đang làm</span>':'<span class="st st-muted">Đã đóng</span>'}</td><td>${a.duration!=null?Math.round(a.duration/60)+' phút':'—'}</td><td>${a.violations||0}</td>${self?'':`<td><button class="link" data-attempt="${esc(a.id)}">Chi tiết</button></td>`}</tr>`).join('')||'<tr><td colspan="7" class="muted">Chưa có bài làm.</td></tr>'}</tbody></table></div><div id="attempt-detail"></div></section>
 ${self?'':`<section class="card no-print-notes"><h2>Ghi chú riêng của giáo viên</h2><p class="small muted">Chỉ giáo viên tạo ghi chú và quản trị viên xem được; học sinh không thấy.</p><form id="note-form" class="no-print"><textarea id="note-text" rows="3" maxlength="2000" required placeholder="Ví dụ: Em tiến bộ ở chủ đề B, cần nhắc làm bài đúng hạn."></textarea><div class="form-row"><button class="primary">Lưu ghi chú</button></div></form><ul class="notes">${r.notes.map(n=>`<li><p>${esc(n.text)}</p><small class="muted">${esc(n.authorName||n.authorId)} · ${fmtD(n.createdAt)}</small> <button class="link no-print" data-note="${esc(n.id)}">Xóa</button></li>`).join('')||'<li class="muted small">Chưa có ghi chú.</li>'}</ul></section>`}
 <p class="small muted rp-foot">Thang đánh giá: Giỏi ≥ 8,0 · Khá 6,5–&lt;8,0 · Đạt 5,0–&lt;6,5 · Chưa đạt &lt; 5,0 (theo điểm trung bình 10 bài kiểm tra gần nhất, không tính luyện tập). Nhận xét được hệ thống tự động tổng hợp, giáo viên cần xem xét trước khi sử dụng chính thức.</p></article>`}
function bindReport(m,r){const back=$('#rp-back');if(back)back.onclick=()=>renderPortal('students');const pr=$('#rp-print');if(pr)pr.onclick=()=>print();bindAttemptLinks(m);
 const nf=$('#note-form');if(nf)nf.onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{await api('noteAdd',{studentId:r.student.id,text:$('#note-text').value});toast('Đã lưu ghi chú.');renderPortal('report')})};
 m.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>run(b,async()=>{if(!confirm('Xóa ghi chú này?'))return;await api('noteDelete',{id:b.dataset.note});renderPortal('report')}))}
function bindAttemptLinks(m){m.querySelectorAll('[data-attempt]').forEach(b=>b.onclick=()=>run(b,async()=>{const x=await api('attemptDetail',{id:b.dataset.attempt}),a=x.attempt,box=$('#attempt-detail');const val=(q,v)=>v==null?'<i>Bỏ trống</i>':q.type==='tf'?(v?'Đúng':'Sai'):esc(q.options?.[v]);
  box.innerHTML=`<div class="attempt-box"><div class="section-head"><h3>${esc(a.title)} · ${a.status==='submitted'?fmt(a.score)+'/10':a.status==='active'?'Đang làm '+esc(a.progress):'Đã đóng'}</h3><button class="link" id="ad-close">Đóng ✕</button></div><p class="small muted">${fmtD(a.startedAt)} → ${fmtD(a.finishedAt)} · ${esc(a.reason||'')} · ${a.violations.length} vi phạm</p>${a.answers.length?`<ol class="ad-list">${a.answers.map(q=>`<li class="${q.correct?'ok':'bad'}"><div class="qtext">${esc(q.question)}</div><small>Đã chọn: <b>${val(q,q.selected)}</b>${q.correct?' ✓':` ✗ · Đáp án: <b>${val(q,q.answer)}</b>`}${q.seconds!=null?` · ${q.seconds}s`:''} · Bài ${q.lesson} · ${esc(q.level||'')}</small></li>`).join('')}</ol>`:'<p class="small muted">Chưa có câu trả lời được chấm.</p>'}</div>`;$('#ad-close').onclick=()=>box.innerHTML='';box.scrollIntoView({behavior:'smooth',block:'start'})}))}
/* ---------- class analytics ---------- */
async function analyticsView(m){const d=PT.data;m.innerHTML=head('Phân tích lớp','Điểm, phân bố, câu hỏi khó, chủ đề yếu và học sinh cần quan tâm.',`<button class="ghost" id="an-export">⬇ Xuất Excel</button>`)+
 `<div class="toolbar p-toolbar"><select id="an-class" aria-label="Lớp">${classOpts(PT.cls,true)}</select><select id="an-exam" aria-label="Đề"><option value="">Tất cả bài (không tính luyện tập)</option>${d.exams.map(e=>`<option value="${esc(e.id)}" ${PT.exam===e.id?'selected':''}>${esc(e.title)}</option>`).join('')}</select></div><div id="an-out"><p class="loading">Đang phân tích…</p></div><section class="card"><h2>So sánh các lớp</h2><div id="an-compare"><p class="loading">…</p></div></section>`;
 const load=async()=>{PT.cls=$('#an-class').value;PT.exam=$('#an-exam').value;const x=await api('classStats',{classId:PT.cls||undefined,examId:PT.exam||undefined}),a=x.analytics,s=a.summary,out=$('#an-out');
  out.innerHTML=`<div class="metric-grid p-metrics">${metric(s.students,'Học sinh')}${metric(fmt(s.average),'Điểm TB các bài')}${metric(s.passRate==null?'—':s.passRate+'%','Bài đạt ≥ 5')}${metric(s.completionRate==null?'—':s.completionRate+'%','Hoàn thành đúng hạn')}${metric(s.atRisk,'Cần quan tâm','warn')}</div>
  <div class="p-grid2"><section class="card"><h2>Phân bố điểm (${s.attempts} bài)</h2>${barChart(a.histogram,{color:i=>i<5?'low':i<8?'mid':'high'})}</section><section class="card"><h2>Xếp mức học sinh</h2>${barChart(Object.entries(s.ratingCounts).map(([label,count])=>({label,count})),{color:i=>['high','mid','pass','low'][i]})}<p class="small muted">Trung vị ${fmt(s.median)} · HS có TB ≥ 5: ${s.studentPassRate==null?'—':s.studentPassRate+'%'}</p></section></div>
  <div class="p-grid2"><section class="card"><h2>Chủ đề / bài yếu nhất</h2>${hbars([...a.topics.map(t=>({label:'Chủ đề '+t.id,value:t.accuracy})),...a.lessons.slice(0,6).map(l=>({label:'Bài '+l.id+' · '+l.title,value:l.accuracy}))].sort((x,y)=>x.value-y.value).slice(0,10))}</section><section class="card"><h2>Học sinh cần quan tâm</h2>${riskList(a.atRisk.slice(0,12))}</section></div>
  ${a.trend.length?`<section class="card"><h2>Điểm trung bình theo tháng</h2>${lineChart(a.trend.map(t=>({score:t.average,at:t.month+'-01',title:t.month+' ('+t.n+' bài)'})))}</section>`:''}
  <section class="card"><h2>Bảng xếp hạng</h2><div class="table-wrap"><table class="p-table"><thead><tr><th>#</th><th>Học sinh</th><th>Lớp</th><th>TB gần đây</th><th>Mức</th><th>Số bài</th><th>Xu hướng</th><th>Bài giao</th><th>Vi phạm</th></tr></thead><tbody>${a.ranking.map(r=>`<tr class="${r.atRisk?'risk-row':''}"><td>${r.rank??'—'}</td><td><button class="link" data-student="${esc(r.id)}">${esc(r.name)}</button></td><td>${esc(r.className)}</td><td><b>${fmt(r.recentAverage)}</b></td><td>${rateTag(r.rating)}</td><td>${r.count}</td><td>${esc(r.trend)}</td><td>${r.completion.onTime}/${r.completion.onTime+r.completion.late+r.completion.missing}${r.completion.missing?` <span class="chip warn">thiếu ${r.completion.missing}</span>`:''}</td><td>${r.violations}</td></tr>`).join('')||'<tr><td colspan="9" class="muted">Chưa có học sinh.</td></tr>'}</tbody></table></div></section>
  <section class="card"><h2>Phân tích câu hỏi</h2><p class="small muted">p = tỉ lệ làm đúng (độ khó); D = độ phân biệt giữa nhóm 27% điểm cao và 27% điểm thấp (D ≥ 0,3 tốt; &lt; 0,2 cần xem lại). Thanh màu = tỉ lệ chọn từng phương án (xanh = đáp án đúng).</p><div class="table-wrap scroll-y tall"><table class="p-table items"><thead><tr><th>Câu</th><th>Bài</th><th>n</th><th>p</th><th>D</th><th>Lựa chọn</th><th>Cảnh báo</th></tr></thead><tbody>${a.items.slice(0,150).map(i=>`<tr><td class="qtext">${esc(i.question)}</td><td>${i.lesson}<br><small>${esc(i.level||'')}</small></td><td>${i.n}</td><td><b>${fmt(i.p)}</b><br><small>${i.difficulty}</small></td><td>${i.discrimination==null?'—':fmt(i.discrimination)}</td><td><div class="dist">${i.choices.map((c,k)=>`<span class="${k===i.answer?'key':''}" style="flex:${Math.max(c,0.0001)}" title="${esc((i.type==='mcq'?'ABCD'[k]+'. ':'')+(i.options?.[k]||''))}: ${c}">${i.type==='mcq'?'ABCD'[k]:k?'S':'Đ'}${c}</span>`).join('')}${i.blank?`<span class="blank" style="flex:${i.blank}" title="Bỏ trống: ${i.blank}">∅${i.blank}</span>`:''}</div></td><td>${i.flags.map(f=>`<span class="chip warn">${esc(f)}</span>`).join(' ')}</td></tr>`).join('')||'<tr><td colspan="7" class="muted">Chưa có bài làm được chấm.</td></tr>'}</tbody></table></div></section>`;bindStudentLinks(out)};
 $('#an-class').onchange=()=>run(null,load);$('#an-exam').onchange=()=>run(null,load);$('#an-export').onclick=e=>run(e.target,async()=>{const x=await api('classExport',{classId:$('#an-class').value||undefined,examId:$('#an-exam').value||undefined});downloadB64(x.filename,x.base64)});
 await run(null,load);run(null,async()=>{const c=await api('classCompare');$('#an-compare').innerHTML=c.rows.length?`<div class="table-wrap"><table class="p-table"><thead><tr><th>Lớp</th><th>HS</th><th>HS đã làm bài</th><th>Điểm TB</th><th>Bài đạt ≥5</th><th>Hoàn thành đúng hạn</th><th>Giỏi/Khá/Đạt/Chưa đạt</th><th>Chủ đề yếu nhất</th><th>Cần quan tâm</th></tr></thead><tbody>${c.rows.map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${r.students}</td><td>${r.activeStudents}</td><td>${fmt(r.average)}</td><td>${r.passRate==null?'—':r.passRate+'%'}</td><td>${r.completionRate==null?'—':r.completionRate+'%'}</td><td>${Object.values(r.ratingCounts).join(' / ')}</td><td>${r.weakest?'Chủ đề '+r.weakest.id+' ('+r.weakest.accuracy+'%)':'—'}</td><td>${r.atRisk}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted small">Chưa có lớp.</p>'})}
/* ---------- assignments ---------- */
const localISO=t=>{const d=new Date(t-new Date().getTimezoneOffset()*60000);return d.toISOString().slice(0,16)};
async function assignView(m){const d=PT.data,now=Date.now();const mine=d.exams.filter(e=>e.ownerId);
 m.innerHTML=head('Giao bài','Giao đề trong ngân hàng hoặc đề bạn tự tạo cho từng lớp, có giờ mở/đóng, số lượt làm và thời điểm hiện đáp án.')+
 `<form class="card" id="as-form"><div class="p-form-grid"><div><label for="as-class">Lớp</label><select id="as-class" required>${classOpts(PT.cls)}</select></div><div><label for="as-exam">Đề</label><select id="as-exam" required>${mine.length?`<optgroup label="Đề của tôi">${mine.map(e=>`<option value="${esc(e.id)}">${esc(e.title)} (${e.mcq} TN + ${e.tf} Đ/S)</option>`).join('')}</optgroup>`:''}<optgroup label="Ngân hàng đề">${d.exams.filter(e=>!e.ownerId&&!e.custom).map(e=>`<option value="${esc(e.id)}">${esc(e.title)}</option>`).join('')}</optgroup></select></div>
 <div><label for="as-open">Mở lúc</label><input type="datetime-local" id="as-open" required value="${localISO(now)}"></div><div><label for="as-close">Đóng lúc</label><input type="datetime-local" id="as-close" required value="${localISO(now+7*86400000)}"></div>
 <div><label for="as-limit">Số lượt làm tối đa</label><input type="number" id="as-limit" min="1" max="20" value="1"></div><div><label for="as-show">Hiện đáp án</label><select id="as-show"><option value="after_close">Sau khi đóng bài</option><option value="after_submit">Ngay sau khi nộp</option><option value="never">Không hiện</option></select></div></div><div class="form-row"><button class="primary">Giao bài</button></div></form>
 <div class="section-head"><h2>Bài đã giao</h2></div><div class="table-wrap"><table class="p-table"><thead><tr><th>Bài</th><th>Lớp</th><th>Mở</th><th>Đóng</th><th>Lượt</th><th>Đáp án</th><th>Trạng thái</th><th></th></tr></thead><tbody>${d.assignments.map(a=>`<tr><td><b>${esc(a.title)}</b></td><td>${esc(a.className)}</td><td><small>${fmtD(a.opensAt)}</small></td><td><small>${fmtD(a.closesAt)}</small></td><td>${a.attemptLimit||'—'}</td><td><small>${({after_close:'Sau khi đóng',after_submit:'Sau khi nộp',never:'Không'})[a.showAnswers]||'Theo đề'}</small></td><td>${a.disabled?'<span class="st st-muted">Đã hủy</span>':now<a.opensAt?'<span class="st st-muted">Sắp mở</span>':now<a.closesAt?'<span class="st st-info">Đang mở</span>':'<span class="st st-ok">Đã đóng</span>'}</td><td class="row-actions"><button class="ghost sm" data-astats="${esc(a.examId)}" data-aclass="${esc(a.classId||'')}">Kết quả</button>${!a.disabled&&(isAdminP()||a.ownerId===user.id)?`<button class="ghost sm" data-aclose="${esc(a.id)}">Hủy</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">Chưa giao bài nào.</td></tr>'}</tbody></table></div>`;
 $('#as-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{await api('assignmentSave',{classId:$('#as-class').value,examId:$('#as-exam').value,opensAt:new Date($('#as-open').value).toISOString(),closesAt:new Date($('#as-close').value).toISOString(),attemptLimit:+$('#as-limit').value,showAnswers:$('#as-show').value});toast('Đã giao bài.');renderPortal('assign')})};
 m.querySelectorAll('[data-aclose]').forEach(b=>b.onclick=()=>run(b,async()=>{if(!confirm('Hủy bài giao này? Học sinh sẽ không thấy bài nữa.'))return;await api('assignmentClose',{id:b.dataset.aclose});renderPortal('assign')}));
 m.querySelectorAll('[data-astats]').forEach(b=>b.onclick=()=>{PT.exam=b.dataset.astats;PT.cls=b.dataset.aclass;renderPortal('analytics')})}
/* ---------- exam builder ---------- */
async function builderView(m){const d=PT.data;const mine=d.exams.filter(e=>e.ownerId||(isAdminP()&&e.custom));
 m.innerHTML=head('Tạo đề','Chọn từng câu từ ngân hàng (kể cả câu bạn tự nhập) hoặc tạo ngẫu nhiên theo ma trận bài × mức độ.',`<span class="pill">Ngân hàng: ${d.bankSize.mcq} TN · ${d.bankSize.tf} Đ/S</span>`)+
 `<div class="seg" role="tablist"><button data-mode="pick" class="${PT.mode!=='blueprint'?'on':''}">Chọn từng câu</button><button data-mode="blueprint" class="${PT.mode==='blueprint'?'on':''}">Ngẫu nhiên theo ma trận</button></div><div id="b-body"></div>
 <div class="section-head"><h2>Đề của tôi</h2></div><div class="table-wrap"><table class="p-table"><thead><tr><th>Đề</th><th>Số câu</th><th>Chủ đề</th><th></th></tr></thead><tbody>${mine.map(e=>`<tr><td><b>${esc(e.title)}</b><br><small class="muted">${esc(e.id)}</small></td><td>${e.mcq} TN + ${e.tf} Đ/S · ${e.minutes} phút</td><td>${esc(e.topics.join(', '))}</td><td class="row-actions"><button class="ghost sm" data-assign="${esc(e.id)}">Giao bài</button><button class="ghost sm" data-del="${esc(e.id)}">Xóa</button></td></tr>`).join('')||'<tr><td colspan="4" class="muted">Chưa có đề tự tạo.</td></tr>'}</tbody></table></div>`;
 m.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{PT.mode=b.dataset.mode;builderView(m)});
 m.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>run(b,async()=>{if(!confirm('Xóa đề này? Bài làm cũ vẫn được giữ.'))return;await api('examDelete',{id:b.dataset.del});PT.data=await api('portalData');renderPortal('builder')}));
 m.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>{renderPortal('assign').then(()=>{const s=$('#as-exam');if(s)s.value=b.dataset.assign})});
 const body=$('#b-body');const lessonOpts=d.lessons.filter(l=>l.id<=28).map(l=>`<option value="${l.id}">Bài ${l.id} – ${esc(l.title)}</option>`).join('');
 if(PT.mode==='blueprint'){body.innerHTML=`<form class="card" id="bp-form"><label for="bp-title">Tên đề</label><input id="bp-title" required maxlength="120" placeholder="Kiểm tra 15 phút – Chủ đề B"><label>Phạm vi bài (để trống = tất cả)</label><div class="lesson-picks">${d.lessons.filter(l=>l.id<=28).map(l=>`<label class="fchip"><input type="checkbox" class="bp-l" value="${l.id}"> ${l.id}</label>`).join('')}</div><div class="p-form-grid"><div><label for="bp-nb">Nhận biết (NB)</label><input type="number" id="bp-nb" min="0" max="40" value="6"></div><div><label for="bp-th">Thông hiểu (TH)</label><input type="number" id="bp-th" min="0" max="40" value="3"></div><div><label for="bp-vd">Vận dụng (VD)</label><input type="number" id="bp-vd" min="0" max="40" value="1"></div><div><label for="bp-tf">Câu đúng/sai</label><input type="number" id="bp-tf" min="0" max="4" value="0"></div></div><div class="form-row"><button class="primary">Tạo đề ngẫu nhiên</button></div><div id="bp-out"></div></form>`;
  $('#bp-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{const x=await api('examBuild',{mode:'blueprint',title:$('#bp-title').value,lessons:[...m.querySelectorAll('.bp-l:checked')].map(c=>+c.value),levels:{NB:+$('#bp-nb').value,TH:+$('#bp-th').value,VD:+$('#bp-vd').value},tf:+$('#bp-tf').value});toast(`Đã tạo đề ${x.mcq} TN + ${x.tf} Đ/S.`);PT.data=await api('portalData');renderPortal('builder')})};return}
 body.innerHTML=`<div class="p-grid2 builder"><section class="card"><h2>Ngân hàng câu hỏi</h2><div class="toolbar"><select id="bk-type" aria-label="Loại"><option value="mcq">Trắc nghiệm</option><option value="tf" ${PT.bank.type==='tf'?'selected':''}>Đúng/sai</option></select><select id="bk-lesson" aria-label="Bài"><option value="">Mọi bài</option>${lessonOpts}</select><select id="bk-level" aria-label="Mức độ"><option value="">Mọi mức</option><option>NB</option><option>TH</option><option>VD</option></select><input id="bk-q" placeholder="Tìm nội dung" aria-label="Tìm câu hỏi"></div><div id="bk-list" class="bk-list"></div></section>
 <section class="card cart"><h2>Đề đang soạn (<span id="cart-n">0</span>)</h2><label for="ct-title">Tên đề</label><input id="ct-title" maxlength="120" placeholder="Đề kiểm tra của tôi"><ol id="cart-list" class="small"></ol><div class="form-row"><button class="primary" id="ct-save">Lưu đề</button><button class="ghost" id="ct-clear">Xóa hết</button></div></section></div>`;
 $('#bk-lesson').value=PT.bank.lesson;$('#bk-level').value=PT.bank.level;$('#bk-q').value=PT.bank.q;
 const drawCart=()=>{$('#cart-n').textContent=PT.cart.length;$('#cart-list').innerHTML=PT.cart.map((c,i)=>`<li>${c.type==='tf'?'[Đ/S] ':''}${esc(c.text.slice(0,90))} <button class="link" data-rm="${i}">bỏ</button></li>`).join('');$('#cart-list').querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{PT.cart.splice(+b.dataset.rm,1);drawCart();load()})};
 const load=async()=>{PT.bank={type:$('#bk-type').value,lesson:$('#bk-lesson').value,level:$('#bk-level').value,q:$('#bk-q').value};const x=await api('bankList',PT.bank);$('#bk-list').innerHTML=`<p class="small muted">${x.total} câu${x.total>150?' (hiện 150 câu đầu, hãy lọc thêm)':''}</p>`+x.rows.map(q=>{const inCart=PT.cart.some(c=>c.id===q.id&&c.type===q.type);return`<div class="bk-item ${inCart?'in':''}"><div><small class="muted">Bài ${q.lesson} · ${esc(q.level||'Đ/S')}${q.own?' · <b>của tôi</b>':''}</small><p>${esc(q.question)}</p>${q.options?`<ol type="A" class="small">${q.options.map((o,k)=>`<li class="${k===q.answer?'is-key':''}">${esc(o)}</li>`).join('')}</ol>`:''}${q.statements?`<ul class="small">${q.statements.map(s=>`<li>${esc(s.label)}) ${esc(s.text)} — <b>${s.answer?'Đ':'S'}</b></li>`).join('')}</ul>`:''}</div><button class="ghost sm" data-add="${esc(q.id)}" data-t="${q.type}" data-text="${esc(q.question)}" ${inCart?'disabled':''}>${inCart?'Đã thêm':'＋ Thêm'}</button></div>`}).join('');
  $('#bk-list').querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{PT.cart.push({id:b.dataset.add,type:b.dataset.t,text:b.dataset.text});b.disabled=true;b.textContent='Đã thêm';b.closest('.bk-item').classList.add('in');drawCart()})};
 ['bk-type','bk-lesson','bk-level'].forEach(id=>$('#'+id).onchange=()=>run(null,load));let t;$('#bk-q').oninput=()=>{clearTimeout(t);t=setTimeout(()=>run(null,load),300)};
 $('#ct-clear').onclick=()=>{PT.cart=[];drawCart();load()};$('#ct-save').onclick=e=>run(e.target,async()=>{const x=await api('examBuild',{mode:'pick',title:$('#ct-title').value,items:PT.cart.map(c=>({id:c.id,type:c.type}))});PT.cart=[];toast(`Đã lưu đề ${x.mcq} TN + ${x.tf} Đ/S.`);PT.data=await api('portalData');renderPortal('builder')});drawCart();await run(null,load)}
