async function bankView(m){const x=await api('bankList',{type:'mcq',ownOnly:true}),y=await api('bankList',{type:'tf'});const own=[...x.rows,...y.rows].filter(q=>q.own);
 m.innerHTML=head('Ngân hàng câu hỏi của tôi','Câu hỏi bạn nhập chỉ bạn thấy và dùng khi tạo đề.')+`<form class="card" id="qb-form"><p class="small">Mỗi dòng một câu. Trắc nghiệm: <code>N|Câu hỏi|Đáp án đúng|Sai 1|Sai 2|Sai 3|Giải thích|Bài</code> (N/T/V = nhận biết/thông hiểu/vận dụng). Đúng/sai: <code>TF|Tình huống|Đ|Nhận định a|Giải thích|…×4|Bài</code>. Nên viết các phương án dài tương đương nhau để tránh đoán theo độ dài.</p><label for="qb-text">Câu hỏi</label><textarea id="qb-text" rows="6" required placeholder="N|Thiết bị nào dùng để định tuyến gói tin giữa các mạng?|Router|Switch|Hub|Repeater|Router chọn đường đi giữa các mạng.|3"></textarea><div class="form-row"><button class="primary">Nhập vào ngân hàng</button></div><div id="qb-out"></div></form>
 <div class="section-head"><h2>Câu hỏi của tôi (${own.length})</h2></div><div class="bk-list">${own.map(q=>`<div class="bk-item"><div><small class="muted">Bài ${q.lesson||'—'} · ${esc(q.level||'Đ/S')}</small><p>${esc(q.question)}</p></div><button class="ghost sm" data-qdel="${esc(q.id)}">Xóa</button></div>`).join('')||'<p class="muted small">Chưa có câu hỏi riêng.</p>'}</div>`;
 $('#qb-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{const r=await api('bankImport',{title:'Ngân hàng của '+user.name,text:$('#qb-text').value});toast(`Đã nhập ${r.saved} câu.`);if(r.warnings?.length)$('#qb-out').innerHTML=`<div class="notice small">${r.warnings.map(esc).join('<br>')}</div>`;setTimeout(()=>renderPortal('bank'),r.warnings?.length?2500:0)})};
 m.querySelectorAll('[data-qdel]').forEach(b=>b.onclick=()=>run(b,async()=>{await api('bankDelete',{id:b.dataset.qdel});renderPortal('bank')}))}
