async function announceView(m){const d=PT.data;m.innerHTML=head('Thông báo','Thông báo hiển thị trên trang chủ của học sinh trong lớp.')+`<form class="card" id="an-form"><div class="p-form-grid"><div><label for="an-cls">Lớp</label><select id="an-cls" required>${classOpts(PT.cls)}</select></div><div><label for="an-title">Tiêu đề</label><input id="an-title" required maxlength="120"></div></div><label for="an-body">Nội dung</label><textarea id="an-body" rows="3" maxlength="2000"></textarea><div class="form-row"><button class="primary">Gửi thông báo</button></div></form>
 <div class="ann-list">${d.announcements.map(a=>`<article class="card ann"><div><small class="muted">${esc(a.className)} · ${fmtD(a.createdAt)} · ${esc(a.authorName||'')}</small><h3>${esc(a.title)}</h3><p>${esc(a.body)}</p></div>${isAdminP()||a.ownerId===user.id?`<button class="link" data-adel="${esc(a.id)}">Xóa</button>`:''}</article>`).join('')||'<p class="muted small">Chưa có thông báo.</p>'}</div>`;
 $('#an-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{await api('announce',{classId:$('#an-cls').value,title:$('#an-title').value,body:$('#an-body').value});toast('Đã gửi thông báo.');renderPortal('announce')})};m.querySelectorAll('[data-adel]').forEach(b=>b.onclick=()=>run(b,async()=>{await api('announceDelete',{id:b.dataset.adel});renderPortal('announce')}))}
/* ---------- live ---------- */
async function liveView(m){m.innerHTML=head('Trực tuyến','Ai đang trực tuyến và ai đang làm bài (tự cập nhật mỗi 15 giây).')+'<div id="lv-out"><p class="loading">…</p></div>';const draw=async()=>{if(PT.view!=='live'||!$('#lv-out'))return clearInterval(PT.liveTimer);const x=await api('liveStatus');const exam=x.rows.filter(r=>r.inExam),on=x.rows.filter(r=>r.online&&!r.inExam);
  $('#lv-out').innerHTML=`<div class="metric-grid p-metrics">${metric(exam.length,'Đang làm bài')}${metric(on.length,'Trực tuyến')}${metric(x.rows.length-exam.length-on.length,'Ngoại tuyến')}</div><div class="table-wrap"><table class="p-table"><thead><tr><th>Học sinh</th><th>Lớp</th><th>Trạng thái</th><th>Bài đang làm</th><th>Lần cuối</th></tr></thead><tbody>${x.rows.filter(r=>r.inExam||r.online).map(r=>`<tr><td><button class="link" data-student="${esc(r.id)}">${esc(r.name)}</button></td><td>${esc(r.className)}</td><td>${r.inExam?'<span class="st st-info">● Đang làm bài</span>':'<span class="st st-ok">● Trực tuyến</span>'}</td><td>${r.inExam?esc(r.examTitle||'')+' · câu '+esc(r.progress||''):'—'}</td><td><small>${fmtD(r.lastSeen)}</small></td></tr>`).join('')||'<tr><td colspan="5" class="muted">Hiện không có học sinh nào trực tuyến.</td></tr>'}</tbody></table></div><p class="small muted">Cập nhật ${fmtD(x.serverNow)} · Trực tuyến = hoạt động trong 2 phút gần nhất.</p>`;bindStudentLinks($('#lv-out'))};
 await run(null,draw);PT.liveTimer=setInterval(()=>draw().catch(()=>{}),15000)}
/* ---------- admin: teachers ---------- */
async function teachersView(m){const x=await api('teacherList');
 m.innerHTML=head('Giáo viên','Tạo tài khoản giáo viên, đặt lại mật khẩu, khóa/mở và xem tổng quan hoạt động (mang tính tham khảo, không phải điểm xếp loại giáo viên).')+
 `<form class="card" id="tc-form"><h2>Tạo tài khoản giáo viên</h2><p class="small muted">Mỗi dòng một giáo viên: <code>Họ tên, tên đăng nhập (tuỳ chọn), email (tuỳ chọn)</code>. Mật khẩu ngẫu nhiên được tạo và chỉ hiển thị một lần.</p><textarea id="tc-text" rows="4" required placeholder="Nguyễn Thị Hoa&#10;Trần Văn Nam, gv.namtv, nam@truong.edu.vn"></textarea><div class="form-row"><button class="primary">Tạo tài khoản</button></div><div id="tc-out"></div></form>
 <div class="table-wrap"><table class="p-table"><thead><tr><th>Giáo viên</th><th>Lớp</th><th>HS</th><th>Bài giao</th><th>Tham gia 30 ngày</th><th>Hoàn thành đúng hạn</th><th>Điểm TB lớp</th><th>Hoạt động gần nhất</th><th></th></tr></thead><tbody>${x.rows.map(t=>`<tr><td><button class="link" data-teacher="${esc(t.id)}">${esc(t.name)}</button><br><small class="muted"><code>${esc(t.username)}</code>${t.locked?' · <span class="st st-bad">Đã khóa</span>':''}</small></td><td>${t.classes}</td><td>${t.students}</td><td>${t.assignments}</td><td>${t.participation30d==null?'—':t.participation30d+'%'}</td><td>${t.completionRate==null?'—':t.completionRate+'%'}</td><td>${fmt(t.classAverage)}</td><td><small>${fmtD(t.lastActiveAt||t.lastSeen)}</small></td><td class="row-actions"><button class="ghost sm" data-treset="${esc(t.id)}">Đặt lại MK</button><button class="ghost sm" data-tlock="${esc(t.id)}" data-v="${t.locked?0:1}">${t.locked?'Mở khóa':'Khóa'}</button></td></tr>`).join('')||'<tr><td colspan="9" class="muted">Chưa có giáo viên.</td></tr>'}</tbody></table></div>`;
 $('#tc-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{const rows=$('#tc-text').value.split('\n').map(l=>l.split(/[,;\t]/).map(s=>s.trim())).filter(r=>r[0]).map(([name,username,email])=>({name,username,email}));const r=await api('teacherCreate',{rows});credentialsOut($('#tc-out'),r.results,'tai-khoan-giao-vien');PT.data=await api('portalData')})};
 m.querySelectorAll('[data-teacher]').forEach(b=>b.onclick=()=>{PT.teacher=b.dataset.teacher;renderPortal('teacher')});
 m.querySelectorAll('[data-treset]').forEach(b=>b.onclick=()=>run(b,async()=>{if(!confirm('Đặt lại mật khẩu giáo viên này?'))return;const r=await api('teacherUpdate',{id:b.dataset.treset,resetPassword:true});credentialsOut($('#tc-out'),[{name:x.rows.find(t=>t.id===b.dataset.treset)?.name,username:r.username,password:r.password}],'mat-khau-giao-vien');$('#tc-out').scrollIntoView({behavior:'smooth'})}));
 m.querySelectorAll('[data-tlock]').forEach(b=>b.onclick=()=>run(b,async()=>{await api('teacherUpdate',{id:b.dataset.tlock,locked:b.dataset.v==='1'});renderPortal('teachers')}))}
async function teacherView(m){const x=await api('teacherReport',{id:PT.teacher}),t=x.teacher;
 m.innerHTML=head(esc(t.name),'Tổng quan hoạt động giảng dạy — số liệu trung lập để hỗ trợ, không dùng để chấm điểm giáo viên.',`<button class="ghost" id="tv-back">← Giáo viên</button><button class="primary" id="tv-print">🖨 In</button>`)+
 `<div class="metric-grid p-metrics">${metric(t.classes,'Lớp')}${metric(t.students,'Học sinh')}${metric(t.assignments,'Bài đã giao')}${metric(t.customExams,'Đề tự tạo')}${metric(t.participation30d==null?'—':t.participation30d+'%','HS tham gia 30 ngày')}${metric(t.completionRate==null?'—':t.completionRate+'%','Hoàn thành đúng hạn')}${metric(fmt(t.classAverage),'Điểm TB các lớp')}${metric(t.improvement==null?'—':(t.improvement>0?'+':'')+fmt(t.improvement),'Thay đổi điểm TB (tháng đầu → gần nhất)')}</div>
 <div class="p-grid2"><section class="card"><h2>Điểm trung bình theo tháng</h2>${lineChart(t.trend.map(p=>({score:p.average,at:p.month+'-01',title:p.month+' ('+p.n+' bài)'})))}</section><section class="card"><h2>Các lớp phụ trách</h2>${x.classes.length?`<div class="table-wrap"><table><thead><tr><th>Lớp</th><th>HS</th><th>Điểm TB</th><th>Đạt ≥5</th><th>Đúng hạn</th></tr></thead><tbody>${x.classes.map(c=>`<tr><td>${esc(c.name)}</td><td>${c.students}</td><td>${fmt(c.average)}</td><td>${c.passRate==null?'—':c.passRate+'%'}</td><td>${c.completionRate==null?'—':c.completionRate+'%'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted small">Chưa phụ trách lớp nào. Gán lớp tại mục Lớp học.</p>'}</section></div>
 <section class="card"><h2>Nhật ký hoạt động</h2>${t.activity.length?`<div class="table-wrap scroll-y"><table><thead><tr><th>Thời điểm (UTC+7)</th><th>Hoạt động</th><th>Chi tiết</th></tr></thead><tbody>${t.activity.map(a=>`<tr><td><small>${fmtD(a.at)}</small></td><td>${esc(a.action)}</td><td>${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted small">Chưa có hoạt động.</p>'}</section>`;
 $('#tv-back').onclick=()=>renderPortal('teachers');$('#tv-print').onclick=()=>print()}
/* ---------- student: self report + announcements ---------- */
async function myReportHTML(el){el.innerHTML='<p class="loading">Đang lập báo cáo…</p>';const x=await api('myReport');el.innerHTML=(x.busy?'<div class="notice">Bạn còn bài đang làm; báo cáo chỉ tính các bài đã nộp.</div>':'')+`<div class="form-row no-print" style="justify-content:flex-end"><button class="ghost" id="my-print">🖨 In / Lưu PDF</button></div>`+reportHTML(x.report,true);$('#my-print').onclick=()=>print()}
function announcementsHTML(){const a=dashboard?.announcements||[];return a.length?`<section class="ann-strip" aria-label="Thông báo của giáo viên">${a.slice(0,3).map(n=>`<article class="ann-note"><b>📣 ${esc(n.title)}</b>${n.body?`<p>${esc(n.body)}</p>`:''}<small>${esc(n.authorName||'Giáo viên')} · ${fmtD(n.createdAt)}</small></article>`).join('')}</section>`:''}
/* presence heartbeat */
setInterval(()=>{if(typeof user!=='undefined'&&user&&document.visibilityState==='visible')fetch('/api',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'ping',data:{where:typeof active!=='undefined'&&active?'exam':user.role==='student'?'student':'portal'}})}).catch(()=>{})},60000);
